	private PreparedStatement _rep_otd_lerStmt = null;
		
	private void initRep_otd_lerStmt() 
	throws SQLException{
		this._rep_otd_lerStmt = ctsqlConnection.prepareStatement(
				"SELECT "
				+ "cdg" 
				+ ",codper" 
				+ ",codnsz" 
				+ ",fecalt" 
				+ ",fecbaj" 
				+ ",codemp" 
				+ ",codact" 
				+ ",domicilio" 
				+ ",codccc" 
				+ ",codcco" 
				+ ",fecnew" 
				+ ",hornew" 
				+ ",fecmod" 
				+ ",hormod" 
				+ ",contr_temp" 
				+ ",mayor65" 
				+ ",afi" 
				+ ",indagrario" 
				+ ",indgrupo" 
				+ ",pariente" 
				+ ",noirpf" 
				+ " FROM emprper"
				+ " WHERE" 
				+ " cdg = ?  " 			); 
	}

	private void closeRep_otd_lerStmt() 
	throws SQLException{
		if ( _rep_otd_lerStmt != null ) { 
			_rep_otd_lerStmt.close();
			_rep_otd_lerStmt = null;	
		}
	}

	/**
	 * Trabdto
	 * 
	 */
	public class Trabdto {
		
		private ResultSet rs;
		
		protected Trabdto (ResultSet rs) 
		throws SQLException {
			this.rs =rs;
		}
		
		/**
		 * Codigo de Trabajador
		 * @return the column 'cdg' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public Integer getCdg()
		throws SQLException {
			return rs.getInt(1);
		}
		/**
		 * Numero de Orden
		 * @return the column 'orden' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public Integer getOrden()
		throws SQLException {
			return rs.getInt(2);
		}
		/**
		 * Fecha Inicio Vigencia
		 * @return the column 'fecini' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public Date getFecini()
		throws SQLException {
			return rs.getDate(3);
		}
		/**
		 * Fecha Fin Vigencia
		 * @return the column 'fecfin' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public Date getFecfin()
		throws SQLException {
			return rs.getDate(4);
		}
		/**
		 * Numero de Linea en Nomina
		 * @return the column 'linea' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public Integer getLinea()
		throws SQLException {
			return rs.getInt(5);
		}
		/**
		 * Concepto de Minoracion
		 * @return the column 'concepto' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public String getConcepto()
		throws SQLException {
			return rs.getString(6);
		}
		/**
		 * Nominas a las que afecta
		 * @return the column 'afecta' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public String getAfecta()
		throws SQLException {
			return rs.getString(7);
		}
		/**
		 * Importe Minoracion
		 * @return the column 'importe' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public BigDecimal getImporte()
		throws SQLException {
			return rs.getBigDecimal(8);
		}
		/**
		 * Importe a Indicar
		 * @return the column 'indimp' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public String getIndimp()
		throws SQLException {
			return rs.getString(9);
		}
		/**
		 * Fecha Creacion Fila
		 * @return the column 'fecnew' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public Date getFecnew()
		throws SQLException {
			return rs.getDate(10);
		}
		/**
		 * Hora Creacion Fila
		 * @return the column 'hornew' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public Time getHornew()
		throws SQLException {
			return rs.getTime(11);
		}
		/**
		 * Fecha Modificacion Fila
		 * @return the column 'fecmod' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public Date getFecmod()
		throws SQLException {
			return rs.getDate(12);
		}
		/**
		 * Hora Modificacion Fila
		 * @return the column 'hormod' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public Time getHormod()
		throws SQLException {
			return rs.getTime(13);
		}

		/**
		 * Visit Emprper that's parent of this Trabdto. 
		 * @param ctsqlDBVisitor a CtsqlDBVisitor.
		 * @throws SQLException
		 */
		public void visitRel_dto_per(CtsqlDBVisitor ctsqlDBVisitor) throws SQLException{
			ResultSet 			rs 	= null;
			try {
				
				if ( _rep_otd_lerStmt == null )
					 initRep_otd_lerStmt();
				
				_rep_otd_lerStmt.setInt(1, this.getCdg()); 
				rs = _rep_otd_lerStmt.executeQuery();
				Emprper emprper = new Emprper(rs); 
				while ( rs.next() ) {
					ctsqlDBVisitor.visitRel_dto_per(this, emprper);
				}
			}
			finally {
				if ( rs != null )
					rs.close();
			}
		}

	}
	

	
		
	private PreparedStatement pit_remesa_inssStmt = null;
		
	private void initPit_remesa_inssStmt() 
	throws SQLException{
		this.pit_remesa_inssStmt = ctsqlConnection.prepareStatement(
				"SELECT "
				+ "id" 
				+ ",remesa_inss" 
				+ ",empleado" 
				+ ",fecha_baja" 
				+ ",fecha_parte" 
				+ ",numero_colegiado" 
				+ ",cias" 
				+ ",tipo_parte_it" 
				+ ",numero" 
				+ ",tipo_it" 
				+ ",recaida" 
				+ ",prorrateo_coti" 
				+ ",baseant" 
				+ ",diasant" 
				+ ",baseregdia" 
				+ ",basediacg" 
				+ ",basediaacc" 
				+ ",prest60" 
				+ ",prest75" 
				+ ",procesado" 
				+ ",riesgo" 
				+ " FROM remesa_parte_it"
				+ " WHERE" 
				+ " remesa_inss = ?  " 			); 
	}

	private void closePit_remesa_inssStmt() 
	throws SQLException{
		if ( pit_remesa_inssStmt != null ) { 
			pit_remesa_inssStmt.close();
			pit_remesa_inssStmt = null;	
		}
	}


	/**
	 * Remesa_inss
	 * 
	 */
	public class Remesa_inss {
		
		private ResultSet rs;
		
		protected Remesa_inss (ResultSet rs) 
		throws SQLException {
			this.rs =rs;
		}
		
		/**
		 * Identificador unico de la Remesa
		 * @return the column 'id' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public Integer getId()
		throws SQLException {
			return rs.getInt(1);
		}
		/**
		 * Fecha de la remesa
		 * @return the column 'fecha' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public Date getFecha()
		throws SQLException {
			return rs.getDate(2);
		}
		/**
		 * Hora de la remesa
		 * @return the column 'hora' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public Time getHora()
		throws SQLException {
			return rs.getTime(3);
		}


		
		/**
		 * Visit Remesa_parte_it that're children of this Remesa_inss. 
		 * @param ctsqlDBVisitor a CtsqlDBVisitor.
		 * @throws SQLException
		 */
		public void visitPit_remesa_inss(CtsqlDBVisitor ctsqlDBVisitor) throws SQLException{
			ResultSet 			rs 	= null;
			try {
				
				if ( pit_remesa_inssStmt == null )
					 initPit_remesa_inssStmt();
				
				pit_remesa_inssStmt.setInt(1, this.getId()); 
				rs = pit_remesa_inssStmt.executeQuery();
				Remesa_parte_it remesa_parte_it = new Remesa_parte_it(rs); 
				while ( rs.next() ) {
					ctsqlDBVisitor.visitPit_remesa_inss(remesa_parte_it, this);
				}
			}
			finally {
				if ( rs != null )
					rs.close();
			}
		}
	}
	

	


