	private PreparedStatement cliente_delegacionStmt = null;
		
	private void initCliente_delegacionStmt() 
	throws SQLException{
		this.cliente_delegacionStmt = ctsqlConnection.prepareStatement(
				"SELECT "
				+ "cdg" 
				+ ",coddlg" 
				+ ",descripcion" 
				+ ",alias" 
				+ ",fecini" 
				+ ",fecfin" 
				+ ",tipovia" 
				+ ",nomvia" 
				+ ",numero" 
				+ ",otrdir" 
				+ ",codpos" 
				+ ",localidad" 
				+ ",provincia" 
				+ ",persona" 
				+ ",telefono" 
				+ ",telefono2" 
				+ ",telefono3" 
				+ ",fax" 
				+ ",email" 
				+ ",inddoc" 
				+ ",paiemi" 
				+ ",numdoc" 
				+ ",tipemp" 
				+ ",obscli" 
				+ ",fecnew" 
				+ ",hornew" 
				+ ",fecmod" 
				+ ",hormod" 
				+ ",inactivo" 
				+ ",indcal" 
				+ ",indnom" 
				+ ",indcoste" 
				+ ",divisa" 
				+ ",soloases" 
				+ ",envioss" 
				+ " FROM cliente"
				+ " WHERE" 
				+ " coddlg = ?  " 			); 
	}

	private void closeCliente_delegacionStmt() 
	throws SQLException{
		if ( cliente_delegacionStmt != null ) { 
			cliente_delegacionStmt.close();
			cliente_delegacionStmt = null;	
		}
	}

