	private PreparedStatement rel_cli_empStmt = null;
		
	private void initRel_cli_empStmt() 
	throws SQLException{
		this.rel_cli_empStmt = ctsqlConnection.prepareStatement(
				"SELECT "
				+ "cdg" 
				+ ",coddlg" 
				+ ",descripcion" 
				+ ",alias" 
				+ ",fecini" 
				+ ",fecfin" 
				+ ",tipovia" 
				+ ",nomvia" 
				+ ",numero" 
				+ ",otrdir" 
				+ ",codpos" 
				+ ",localidad" 
				+ ",provincia" 
				+ ",persona" 
				+ ",telefono" 
				+ ",telefono2" 
				+ ",telefono3" 
				+ ",fax" 
				+ ",email" 
				+ ",inddoc" 
				+ ",paiemi" 
				+ ",numdoc" 
				+ ",tipemp" 
				+ ",obscli" 
				+ ",fecnew" 
				+ ",hornew" 
				+ ",fecmod" 
				+ ",hormod" 
				+ ",inactivo" 
				+ ",indcal" 
				+ ",indnom" 
				+ ",indcoste" 
				+ ",divisa" 
				+ ",soloases" 
				+ ",envioss" 
				+ " FROM cliente"
				+ " WHERE" 
				+ " tipemp = ?  " 			); 
	}

	private void closeRel_cli_empStmt() 
	throws SQLException{
		if ( rel_cli_empStmt != null ) { 
			rel_cli_empStmt.close();
			rel_cli_empStmt = null;	
		}
	}
		
