	/**
	 * Trabinci
	 * 
	 */
	public class Trabinci {
		
		private ResultSet rs;
		
		protected Trabinci (ResultSet rs) 
		throws SQLException {
			this.rs =rs;
		}
		
		/**
		 * Codigo de Trabajador
		 * @return the column 'cdg' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public Integer getCdg()
		throws SQLException {
			return rs.getInt(1);
		}
		/**
		 * Fecha Inicio Incidencia
		 * @return the column 'fecini' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public Date getFecini()
		throws SQLException {
			return rs.getDate(2);
		}
		/**
		 * Fecha Fin Incidencia
		 * @return the column 'fecfin' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public Date getFecfin()
		throws SQLException {
			return rs.getDate(3);
		}
		/**
		 * Tipo de Incidencia
		 * @return the column 'codinc' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public String getCodinc()
		throws SQLException {
			return rs.getString(4);
		}
		/**
		 * Horas, Dias
		 * @return the column 'cantidad' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public Integer getCantidad()
		throws SQLException {
			return rs.getInt(5);
		}
		/**
		 * Fecha Creacion Fila
		 * @return the column 'fecnew' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public Date getFecnew()
		throws SQLException {
			return rs.getDate(6);
		}
		/**
		 * Hora Creacion Fila
		 * @return the column 'hornew' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public Time getHornew()
		throws SQLException {
			return rs.getTime(7);
		}
		/**
		 * Fecha Modificacion Fila
		 * @return the column 'fecmod' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public Date getFecmod()
		throws SQLException {
			return rs.getDate(8);
		}
		/**
		 * Hora Modificacion Fila
		 * @return the column 'hormod' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public Time getHormod()
		throws SQLException {
			return rs.getTime(9);
		}
		/**
		 * Importe
		 * @return the column 'importe' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public BigDecimal getImporte()
		throws SQLException {
			return rs.getBigDecimal(10);
		}

		/**
		 * Visit Tipinc that's parent of this Trabinci. 
		 * @param ctsqlDBVisitor a CtsqlDBVisitor.
		 * @throws SQLException
		 */
		public void visitRel_inc_tip(CtsqlDBVisitor ctsqlDBVisitor) throws SQLException{
			ResultSet 			rs 	= null;
			try {
				
				if ( _pit_cni_lerStmt == null )
					 initPit_cni_lerStmt();
				
				_pit_cni_lerStmt.setString(1, this.getCodinc()); 
				rs = _pit_cni_lerStmt.executeQuery();
				Tipinc tipinc = new Tipinc(rs); 
				while ( rs.next() ) {
					ctsqlDBVisitor.visitRel_inc_tip(this, tipinc);
				}
			}
			finally {
				if ( rs != null )
					rs.close();
			}
		}
		/**
		 * Visit Emprper that's parent of this Trabinci. 
		 * @param ctsqlDBVisitor a CtsqlDBVisitor.
		 * @throws SQLException
		 */
		public void visitTrabinci_emprper(CtsqlDBVisitor ctsqlDBVisitor) throws SQLException{
			ResultSet 			rs 	= null;
			try {
				
				if ( _reprpme_icnibartStmt == null )
					 initReprpme_icnibartStmt();
				
				_reprpme_icnibartStmt.setInt(1, this.getCdg()); 
				rs = _reprpme_icnibartStmt.executeQuery();
				Emprper emprper = new Emprper(rs); 
				while ( rs.next() ) {
					ctsqlDBVisitor.visitTrabinci_emprper(this, emprper);
				}
			}
			finally {
				if ( rs != null )
					rs.close();
			}
		}

	}
	

	
		
