	private PreparedStatement lcomunica_costesStmt = null;
		
	private void initLcomunica_costesStmt() 
	throws SQLException{
		this.lcomunica_costesStmt = ctsqlConnection.prepareStatement(
				"SELECT "
				+ "cdg" 
				+ ",numero" 
				+ ",orden" 
				+ ",anionac" 
				+ ",xminus" 
				+ ",des_asc" 
				+ ",descen_ent" 
				+ ",conviv" 
				+ " FROM lcomunica"
				+ " WHERE" 
				+ " cdg = ?  "  + "AND" 				+ " numero = ?  " 			); 
	}

