		public void visitComunica_emprper(CtsqlDBVisitor ctsqlDBVisitor) throws SQLException{
			ResultSet 			rs 	= null;
			try {
				
				if ( _reprpme_acinumocStmt == null )
					 initReprpme_acinumocStmt();
				
				_reprpme_acinumocStmt.setInt(1, this.getCdg()); 
				rs = _reprpme_acinumocStmt.executeQuery();
				Emprper emprper = new Emprper(rs); 
				while ( rs.next() ) {
					ctsqlDBVisitor.visitComunica_emprper(this, emprper);
				}
			}
			finally {
				if ( rs != null )
					rs.close();
			}
		}
