	private PreparedStatement rel_tra_autStmt = null;
		
	private void initRel_tra_autStmt() 
	throws SQLException{
		this.rel_tra_autStmt = ctsqlConnection.prepareStatement(
				"SELECT "
				+ "cdg" 
				+ ",fecini" 
				+ ",fecfin" 
				+ ",fecant" 
				+ ",ctacar" 
				+ ",profesion" 
				+ ",codcon" 
				+ ",codcat" 
				+ ",nivel" 
				+ ",descat" 
				+ ",codbas" 
				+ ",codepi" 
				+ ",irpf" 
				+ ",cno" 
				+ ",procot" 
				+ ",proret" 
				+ ",nummat" 
				+ ",codcont" 
				+ ",codtc2" 
				+ ",destc2" 
				+ ",fecinicont" 
				+ ",fecfincont" 
				+ ",diascont" 
				+ ",autorizacion" 
				+ ",fecaut" 
				+ ",codent" 
				+ ",codsuc" 
				+ ",numcta" 
				+ ",plunumaut" 
				+ ",plufecaut" 
				+ ",pluprcmin" 
				+ ",pluprcmax" 
				+ ",coered" 
				+ ",semana" 
				+ ",semanatp" 
				+ ",cantp" 
				+ ",baseant" 
				+ ",indalt" 
				+ ",inddtoit" 
				+ ",inddtootr" 
				+ ",codpct" 
				+ ",indtp" 
				+ ",indirpf" 
				+ ",concol" 
				+ ",indactcon" 
				+ ",especial" 
				+ ",fecnew" 
				+ ",hornew" 
				+ ",fecmod" 
				+ ",hormod" 
				+ ",dc" 
				+ ",historico" 
				+ ",indceutamelilla" 
				+ ",colectivo" 
				+ ",relacion" 
				+ ",ocupacion" 
				+ ",ocupacion2009" 
				+ ",tipotp" 
				+ ",diastp" 
				+ ",guardalegal" 
				+ ",iban" 
				+ " FROM trabajo"
				+ " WHERE" 
				+ " autorizacion = ?  " 			); 
	}

	private void closeRel_tra_autStmt() 
	throws SQLException{
		if ( rel_tra_autStmt != null ) { 
			rel_tra_autStmt.close();
			rel_tra_autStmt = null;	
		}
	}


	/**
	 * Tipaut
	 * 
	 */
	public class Tipaut {
		
		private ResultSet rs;
		
		protected Tipaut (ResultSet rs) 
		throws SQLException {
			this.rs =rs;
		}
		
		/**
		 * Codigo de Tipo de Autorización
		 * @return the column 'cdg' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public String getCdg()
		throws SQLException {
			return rs.getString(1);
		}
		/**
		 * Descripcion de Tipo de Autorización
		 * @return the column 'descripcion' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public String getDescripcion()
		throws SQLException {
			return rs.getString(2);
		}


		
		/**
		 * Visit Trabajo that're children of this Tipaut. 
		 * @param ctsqlDBVisitor a CtsqlDBVisitor.
		 * @throws SQLException
		 */
		public void visitRel_tra_aut(CtsqlDBVisitor ctsqlDBVisitor) throws SQLException{
			ResultSet 			rs 	= null;
			try {
				
				if ( rel_tra_autStmt == null )
					 initRel_tra_autStmt();
				
				rel_tra_autStmt.setString(1, this.getCdg()); 
				rs = rel_tra_autStmt.executeQuery();
				Trabajo trabajo = new Trabajo(rs); 
				while ( rs.next() ) {
					ctsqlDBVisitor.visitRel_tra_aut(trabajo, this);
				}
			}
			finally {
				if ( rs != null )
					rs.close();
			}
		}
	}
	

	


